-- Schema of the Render database vah-postgres (vah_postgres_40zq), read-only from its catalogs on 18 Nov 2026:
-- columns with exact types and defaults, every constraint, index, foreign key, function, trigger and view.
-- Used only to build local rehearsal copies (build_render_copy.sh). No data.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SEQUENCE business_id_seq AS bigint; CREATE SEQUENCE _migrations_id_seq AS integer; CREATE SEQUENCE activity_log_id_seq AS bigint;
CREATE SEQUENCE address_slot_id_seq AS bigint; CREATE SEQUENCE admin_activity_id_seq AS integer; CREATE SEQUENCE admin_audit_id_seq AS integer;
CREATE SEQUENCE admin_log_id_seq AS bigint; CREATE SEQUENCE admin_operation_locks_id_seq AS integer; CREATE SEQUENCE audit_log_id_seq AS bigint;
CREATE SEQUENCE blog_posts_id_seq AS integer; CREATE SEQUENCE concurrent_operations_id_seq AS integer; CREATE SEQUENCE download_id_seq AS bigint;
CREATE SEQUENCE email_preferences_id_seq AS bigint; CREATE SEQUENCE export_job_id_seq AS bigint; CREATE SEQUENCE file_id_seq AS bigint;
CREATE SEQUENCE forwarding_charge_id_seq AS integer; CREATE SEQUENCE forwarding_outbox_id_seq AS integer; CREATE SEQUENCE forwarding_request_id_seq AS integer;
CREATE SEQUENCE gc_billing_request_flow_id_seq AS bigint; CREATE SEQUENCE gc_redirect_flow_id_seq AS bigint; CREATE SEQUENCE invoice_id_seq AS bigint;
CREATE SEQUENCE invoice_seq_id_seq AS bigint; CREATE SEQUENCE invoice_token_id_seq AS bigint; CREATE SEQUENCE kyc_status_id_seq AS bigint;
CREATE SEQUENCE location_id_seq AS bigint; CREATE SEQUENCE mail_event_id_seq AS bigint; CREATE SEQUENCE mail_item_id_seq AS bigint;
CREATE SEQUENCE migrations_id_seq AS integer; CREATE SEQUENCE notification_id_seq AS bigint; CREATE SEQUENCE password_reset_id_seq AS bigint;
CREATE SEQUENCE plan_price_history_id_seq AS bigint; CREATE SEQUENCE plan_status_event_id_seq AS bigint; CREATE SEQUENCE plans_id_seq AS bigint;
CREATE SEQUENCE quiz_leads_id_seq AS bigint; CREATE SEQUENCE scan_tokens_id_seq AS bigint; CREATE SEQUENCE subscription_id_seq AS integer;
CREATE SEQUENCE support_ticket_id_seq AS integer; CREATE SEQUENCE usage_charges_id_seq AS integer; CREATE SEQUENCE user_id_seq AS bigint;
CREATE SEQUENCE user_profile_id_seq AS bigint; CREATE SEQUENCE webhook_log_id_seq AS bigint; CREATE SEQUENCE email_change_request_id_seq AS bigint;
CREATE SEQUENCE business_owner_id_seq AS bigint; CREATE SEQUENCE business_owner_invite_id_seq AS bigint; CREATE SEQUENCE destruction_log_id_seq AS integer;

CREATE TABLE _migrations (id integer DEFAULT nextval('_migrations_id_seq'::regclass) NOT NULL, name text NOT NULL, applied_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE activity_log (id bigint DEFAULT nextval('activity_log_id_seq'::regclass) NOT NULL, created_at bigint NOT NULL, user_id bigint, action text NOT NULL, details text, mail_item_id bigint, ip_address text, user_agent text);
CREATE TABLE address_slot (id bigint DEFAULT nextval('address_slot_id_seq'::regclass) NOT NULL, location_id bigint NOT NULL, mailbox_no text NOT NULL, status text DEFAULT 'available'::text NOT NULL, assigned_to bigint, assigned_at timestamp with time zone, reserved_until timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, created_at_ms bigint);
CREATE TABLE admin_activity (id integer DEFAULT nextval('admin_activity_id_seq'::regclass) NOT NULL, admin_id integer, action text NOT NULL, target_type text, target_id integer, details jsonb, ip_address text, user_agent text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE admin_audit (id integer DEFAULT nextval('admin_audit_id_seq'::regclass) NOT NULL, admin_id integer NOT NULL, action character varying(100) NOT NULL, target_user_id integer, meta jsonb, created_at timestamp with time zone DEFAULT now(), target_type text, target_id bigint, details text);
CREATE TABLE admin_log (id bigint DEFAULT nextval('admin_log_id_seq'::regclass) NOT NULL, created_at bigint NOT NULL, admin_user_id bigint NOT NULL, action_type text NOT NULL, target_type text, target_id bigint, details text, ip_address text);
CREATE TABLE admin_operation_locks (id integer DEFAULT nextval('admin_operation_locks_id_seq'::regclass) NOT NULL, operation_type text NOT NULL, resource_id text, admin_id integer, locked_at timestamp with time zone DEFAULT now(), expires_at timestamp with time zone NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE audit_log (id bigint DEFAULT nextval('audit_log_id_seq'::regclass) NOT NULL, entity text NOT NULL, entity_id text, action text NOT NULL, meta jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE blog_posts (id integer DEFAULT nextval('blog_posts_id_seq'::regclass) NOT NULL, slug character varying(255) NOT NULL, title text NOT NULL, description text, content text NOT NULL, excerpt text, date timestamp with time zone DEFAULT now() NOT NULL, updated timestamp with time zone, tags text[] DEFAULT '{}'::text[], cover text, status character varying(20) DEFAULT 'draft'::character varying, og_title text, og_desc text, noindex boolean DEFAULT false, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, author_name text DEFAULT 'Liban Adan'::text, author_title text DEFAULT 'Founder, VirtualAddressHub'::text, author_image text DEFAULT '/images/authors/liban.jpg'::text);
CREATE TABLE business (id bigint DEFAULT nextval('business_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, company_name text NOT NULL, trading_name text, companies_house_number text, status text DEFAULT 'active'::text NOT NULL, is_primary boolean DEFAULT false NOT NULL, monthly_price_pence integer DEFAULT 999 NOT NULL, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE TABLE business_owner (id bigint DEFAULT nextval('business_owner_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, full_name text NOT NULL, email text NOT NULL, sumsub_applicant_id text, status text DEFAULT 'not_started'::text NOT NULL, kyc_updated_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, role text NOT NULL, requires_verification boolean DEFAULT true NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE business_owner_invite (id bigint DEFAULT nextval('business_owner_invite_id_seq'::regclass) NOT NULL, business_owner_id bigint NOT NULL, token_hash text NOT NULL, expires_at timestamp with time zone NOT NULL, used_at timestamp with time zone, last_sent_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE charge (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id bigint NOT NULL, amount_pence integer NOT NULL, currency text DEFAULT 'GBP'::text NOT NULL, type text NOT NULL, description text NOT NULL, service_date date NOT NULL, status text DEFAULT 'pending'::text NOT NULL, invoice_id bigint, related_type text, related_id bigint, created_at timestamp with time zone DEFAULT now() NOT NULL, billed_at timestamp with time zone);
CREATE TABLE concurrent_operations (id integer DEFAULT nextval('concurrent_operations_id_seq'::regclass) NOT NULL, operation_type text NOT NULL, resource_id text, user_id integer, status text DEFAULT 'running'::text, started_at timestamp with time zone DEFAULT now(), completed_at timestamp with time zone, error_message text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE destruction_log (id integer DEFAULT nextval('destruction_log_id_seq'::regclass) NOT NULL, mail_item_id integer NOT NULL, user_id integer NOT NULL, user_display_name text NOT NULL, receipt_date date NOT NULL, eligibility_date date NOT NULL, recorded_at timestamp with time zone DEFAULT now() NOT NULL, destruction_status text DEFAULT 'completed'::text NOT NULL, staff_name text NOT NULL, staff_initials text NOT NULL, notes text NOT NULL, destruction_method text DEFAULT 'Cross-cut shredder'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, actor_type text DEFAULT 'admin'::text NOT NULL, action_source text DEFAULT 'admin_ui'::text NOT NULL, staff_user_id integer);
CREATE TABLE download (id bigint DEFAULT nextval('download_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, file_id bigint, download_url text NOT NULL, expires_at bigint NOT NULL, created_at bigint NOT NULL, ip_address text, user_agent text);
CREATE TABLE email_change_request (id bigint DEFAULT nextval('email_change_request_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, new_email text NOT NULL, token_hash text NOT NULL, expires_at timestamp with time zone NOT NULL, used_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, last_sent_at timestamp with time zone);
CREATE TABLE email_preferences (id bigint DEFAULT nextval('email_preferences_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, email_unsubscribed_at timestamp with time zone, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE export_job (id bigint DEFAULT nextval('export_job_id_seq'::regclass) NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, started_at timestamp with time zone, completed_at timestamp with time zone, finished_at timestamp with time zone, status text DEFAULT 'pending'::text NOT NULL, type text, kind text, params jsonb DEFAULT '{}'::jsonb NOT NULL, file_path text, file_size bigint, error text, error_message text, user_id bigint, token text, expires_at bigint, storage_expires_at bigint GENERATED ALWAYS AS (expires_at) STORED, created_at_ms bigint, started_at_ms bigint, completed_at_ms bigint, finished_at_ms bigint);
CREATE TABLE file (id bigint DEFAULT nextval('file_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, mail_item_id bigint, drive_id text, item_id text, path text, name text, size bigint DEFAULT 0, mime text, etag text, modified_at bigint, web_url text, deleted boolean DEFAULT false, created_at bigint NOT NULL, updated_at bigint);
CREATE TABLE forwarding_charge (id integer DEFAULT nextval('forwarding_charge_id_seq'::regclass) NOT NULL, forwarding_request_id integer, amount_pence integer DEFAULT 200, status text DEFAULT 'pending'::text, created_at bigint NOT NULL, updated_at bigint, user_id integer, mail_item_id integer, invoice_id integer);
CREATE TABLE forwarding_outbox (id integer DEFAULT nextval('forwarding_outbox_id_seq'::regclass) NOT NULL, forwarding_request_id integer, event text, payload_json text, status text DEFAULT 'pending'::text, attempt_count integer DEFAULT 0, last_error text, next_attempt_at bigint, created_at bigint NOT NULL, updated_at bigint);
CREATE TABLE forwarding_request (id integer DEFAULT nextval('forwarding_request_id_seq'::regclass) NOT NULL, created_at bigint NOT NULL, user_id integer, mail_item_id integer, status text DEFAULT 'Requested'::text, to_name text, address1 text, address2 text, city text, state text, postal text, country text, reason text, method text, idem_key text, updated_at bigint, tracking text, courier text, reviewed_at bigint, reviewed_by integer, processing_at bigint, dispatched_at bigint, delivered_at bigint, cancelled_at bigint, tracking_number text, admin_notes text);
CREATE TABLE gc_billing_request_flow (id bigint DEFAULT nextval('gc_billing_request_flow_id_seq'::regclass) NOT NULL, created_at_ms bigint NOT NULL, user_id bigint NOT NULL, plan_id bigint NOT NULL, billing_request_id text NOT NULL, billing_request_flow_id text, customer_id text, status text DEFAULT 'created'::text NOT NULL, completed_at_ms bigint);
CREATE TABLE gc_redirect_flow (id bigint DEFAULT nextval('gc_redirect_flow_id_seq'::regclass) NOT NULL, created_at_ms bigint NOT NULL, user_id bigint NOT NULL, plan_id bigint NOT NULL, flow_id text NOT NULL, session_token text, status text DEFAULT 'created'::text NOT NULL, completed_at_ms bigint);
CREATE TABLE invoice_token (id bigint DEFAULT nextval('invoice_token_id_seq'::regclass) NOT NULL, invoice_id bigint NOT NULL, token text NOT NULL, expires_at text NOT NULL, used_at text, created_at bigint NOT NULL, created_at_ms bigint NOT NULL, expires_at_ms bigint NOT NULL, used_at_ms bigint, created_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((created_at_ms)::numeric / 1000.0))::double precision)) STORED, expires_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((expires_at_ms)::numeric / 1000.0))::double precision)) STORED, used_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((used_at_ms)::numeric / 1000.0))::double precision)) STORED);
CREATE TABLE invoices (id bigint DEFAULT nextval('invoice_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, invoice_number text NOT NULL, amount_pence bigint NOT NULL, period_start text NOT NULL, period_end text NOT NULL, pdf_path text, status text DEFAULT 'issued'::text, created_at bigint NOT NULL, number text NOT NULL, billing_interval text, gocardless_payment_id text, currency text DEFAULT 'GBP'::text, email_sent_at timestamp with time zone, email_send_error text, stripe_invoice_id text, stripe_payment_intent_id text);
CREATE TABLE invoices_seq (id bigint DEFAULT nextval('invoice_seq_id_seq'::regclass) NOT NULL, year bigint NOT NULL, sequence bigint DEFAULT 0 NOT NULL, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE TABLE kyc_status (id bigint DEFAULT nextval('kyc_status_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, sumsub_applicant_id text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE location (id bigint DEFAULT nextval('location_id_seq'::regclass) NOT NULL, name text NOT NULL, line1 text NOT NULL, line2 text, city text NOT NULL, postcode text NOT NULL, country text DEFAULT 'United Kingdom'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE mail_event (id bigint DEFAULT nextval('mail_event_id_seq'::regclass) NOT NULL, created_at bigint NOT NULL, mail_item bigint NOT NULL, actor_user bigint, event_type text NOT NULL, details text);
CREATE TABLE mail_item (id bigint DEFAULT nextval('mail_item_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, subject text, sender_name text, received_date text, scan_file_url text, file_size bigint DEFAULT 0, forwarded_physically boolean DEFAULT false, notes text, forwarded_date text, forward_reason text, scanned boolean DEFAULT false, deleted boolean DEFAULT false, tag text, is_billable_forward boolean DEFAULT false, admin_note text, deleted_by_admin boolean DEFAULT false, action_log text, scanned_at bigint, status text DEFAULT 'received'::text, requested_at bigint, physical_receipt_timestamp bigint, physical_dispatch_timestamp bigint, tracking_number text, updated_at bigint, created_at bigint NOT NULL, idempotency_key text, file_id bigint, expires_at bigint, received_at_ms bigint, forwarded_at_ms bigint, received_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((received_at_ms)::numeric / 1000.0))::double precision)) STORED, forwarded_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((forwarded_at_ms)::numeric / 1000.0))::double precision)) STORED, is_read boolean DEFAULT false, forwarding_status text DEFAULT 'No'::text, updated_by bigint, item_id bigint, description text, file_url text, public_url text, mailroom_expiry_notified_at bigint, locked_reason text, locked boolean DEFAULT false NOT NULL, physical_destruction_date timestamp with time zone, destruction_logged boolean DEFAULT false, business_id bigint NOT NULL, source_slug text, mail_type text);
CREATE TABLE migrations (id integer DEFAULT nextval('migrations_id_seq'::regclass) NOT NULL, name character varying(255) NOT NULL, applied_at timestamp without time zone DEFAULT now());
CREATE TABLE notification (id bigint DEFAULT nextval('notification_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, type text NOT NULL, title text NOT NULL, body text, read boolean DEFAULT false, created_at timestamp with time zone DEFAULT now());
CREATE TABLE password_reset (id bigint DEFAULT nextval('password_reset_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, token text NOT NULL, created_at bigint NOT NULL, used_at bigint);
CREATE TABLE plan_price_history (id bigint DEFAULT nextval('plan_price_history_id_seq'::regclass) NOT NULL, plan_id bigint NOT NULL, price_pence bigint NOT NULL, currency text DEFAULT 'GBP'::text NOT NULL, effective_at text DEFAULT (now())::text NOT NULL, note text);
CREATE TABLE plan_status_event (id bigint DEFAULT nextval('plan_status_event_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, subscription_id bigint, old_status text, new_status text NOT NULL, reason text NOT NULL, gocardless_event_id text, gocardless_event_type text, gocardless_event_created_at timestamp with time zone, metadata jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE plans (id bigint DEFAULT nextval('plans_id_seq'::regclass) NOT NULL, name text NOT NULL, slug text NOT NULL, description text, price_pence bigint NOT NULL, "interval" text NOT NULL, currency text DEFAULT 'GBP'::text NOT NULL, features_json text DEFAULT '[]'::text NOT NULL, active boolean DEFAULT false NOT NULL, vat_inclusive boolean DEFAULT true NOT NULL, trial_days bigint DEFAULT 0 NOT NULL, sort bigint DEFAULT 0 NOT NULL, effective_at text, retired_at text, created_at text DEFAULT (now())::text NOT NULL, updated_at text DEFAULT (now())::text NOT NULL, amount_pence integer DEFAULT 0 NOT NULL, created_at_ms bigint DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint NOT NULL, updated_at_ms bigint DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint NOT NULL, effective_at_ms bigint DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint NOT NULL, retired_at_ms bigint, created_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((created_at_ms)::numeric / 1000.0))::double precision)) STORED, updated_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((updated_at_ms)::numeric / 1000.0))::double precision)) STORED, effective_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((effective_at_ms)::numeric / 1000.0))::double precision)) STORED, retired_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((retired_at_ms)::numeric / 1000.0))::double precision)) STORED, billing_cycle text, billing_interval text);
CREATE TABLE quiz_leads (id bigint DEFAULT nextval('quiz_leads_id_seq'::regclass) NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, name text, email text NOT NULL, score integer DEFAULT 0 NOT NULL, answers jsonb, segment text DEFAULT 'low'::text NOT NULL, source text DEFAULT 'compliance-check'::text, quiz_id text);
CREATE TABLE scan_tokens (id bigint DEFAULT nextval('scan_tokens_id_seq'::regclass) NOT NULL, token text NOT NULL, mail_item_id bigint NOT NULL, issued_to bigint, expires_at text NOT NULL, used boolean DEFAULT false NOT NULL, created_at text DEFAULT (now())::text NOT NULL, created_at_ms bigint NOT NULL, expires_at_ms bigint NOT NULL, created_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((created_at_ms)::numeric / 1000.0))::double precision)) STORED, expires_at_ts timestamp with time zone GENERATED ALWAYS AS (to_timestamp((((expires_at_ms)::numeric / 1000.0))::double precision)) STORED);
CREATE TABLE subscription (id integer DEFAULT nextval('subscription_id_seq'::regclass) NOT NULL, user_id integer NOT NULL, plan_name text DEFAULT 'Digital Mailbox Plan'::text NOT NULL, cadence text DEFAULT 'monthly'::text NOT NULL, status text DEFAULT 'active'::text NOT NULL, next_charge_at bigint, mandate_id text, created_at bigint DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint NOT NULL, updated_at bigint DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint NOT NULL, customer_id text, last_event_created_at timestamp with time zone, last_event_id text, stripe_subscription_id text);
CREATE TABLE support_ticket (id integer DEFAULT nextval('support_ticket_id_seq'::regclass) NOT NULL, user_id integer, subject text NOT NULL, message text, category text DEFAULT 'general'::text, priority text DEFAULT 'normal'::text, status text DEFAULT 'open'::text, created_at bigint NOT NULL, updated_at bigint NOT NULL);
CREATE TABLE usage_charges (id integer DEFAULT nextval('usage_charges_id_seq'::regclass) NOT NULL, user_id integer NOT NULL, period_yyyymm text NOT NULL, type text NOT NULL, qty integer DEFAULT 1 NOT NULL, amount_pence integer DEFAULT 0 NOT NULL, notes text, created_at bigint NOT NULL);
CREATE TABLE "user" (id bigint DEFAULT nextval('user_id_seq'::regclass) NOT NULL, email text NOT NULL, name text, password text, first_name text, last_name text, is_admin boolean DEFAULT false NOT NULL, role text DEFAULT 'user'::text NOT NULL, kyc_status text DEFAULT 'pending'::text, plan_status text DEFAULT 'active'::text, plan_start_date bigint, onboarding_step text DEFAULT 'signup'::text, email_verified boolean DEFAULT false, email_verified_at bigint, status text DEFAULT 'active'::text, login_attempts integer DEFAULT 0, locked_until bigint, created_at bigint NOT NULL, updated_at bigint NOT NULL, deleted_at timestamp with time zone, phone text, business_type text, country_of_incorporation text, company_number text, company_name text, forward_to_first_name text, forward_to_last_name text, address_line1 text, address_line2 text, city text, postcode text, forward_country text, billing text, price text, reset_token_hash text, reset_token_expires_at timestamp with time zone, reset_token_used_at timestamp with time zone, last_active_at bigint, plan_id bigint, last_login_at bigint, gocardless_customer_id text, gocardless_mandate_id text, gocardless_redirect_flow_id text, kyc_verified_at bigint, email_pref_marketing boolean DEFAULT false NOT NULL, email_pref_product boolean DEFAULT true NOT NULL, email_pref_system boolean DEFAULT true NOT NULL, kyc_verified_at_ms bigint, kyc_rejection_reason text, email_unsubscribed_at timestamp with time zone, state text, sumsub_applicant_id text, postal_code text, country text, subscription_status text, email_bounced_at timestamp with time zone, forwarding_address text, payment_failed_at bigint, payment_retry_count integer DEFAULT 0, payment_grace_until bigint, account_suspended_at bigint, companies_house_verified boolean DEFAULT false NOT NULL, ch_verification_proof_url text, kyc_approved_at timestamp with time zone, ch_reminder_last_sent_at timestamp with time zone, ch_verification_status text DEFAULT 'not_submitted'::text NOT NULL, ch_verification_submitted_at timestamp with time zone, ch_verification_reviewed_at timestamp with time zone, ch_verification_reviewer_id integer, ch_verification_notes text, is_sole_controller boolean NOT NULL, additional_controllers_count integer, controllers_declared_at timestamp with time zone, owners_pending_info boolean DEFAULT false NOT NULL, stripe_customer_id text, stripe_default_payment_method_id text, companies_house_number text, sumsub_review_status text, sumsub_last_updated bigint, sumsub_rejection_reason text, sumsub_webhook_payload text, reset_token_lookup_hash text);
CREATE TABLE user_profile (id bigint DEFAULT nextval('user_profile_id_seq'::regclass) NOT NULL, user_id bigint NOT NULL, state text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE webhook_log (id bigint DEFAULT nextval('webhook_log_id_seq'::regclass) NOT NULL, source text, event_type text, payload_json text, created_at bigint NOT NULL, provider text NOT NULL, status text, payload jsonb, received_at timestamp with time zone DEFAULT now(), received_at_ms bigint, external_event_id text);

ALTER TABLE ONLY public."user" ADD CONSTRAINT check_controllers_declaration CHECK (((is_sole_controller IS NULL) OR ((is_sole_controller = true) AND ((additional_controllers_count IS NULL) OR (additional_controllers_count = 0))) OR ((is_sole_controller = false) AND ((additional_controllers_count IS NULL) OR (additional_controllers_count >= 1)))));
ALTER TABLE ONLY public."user" ADD CONSTRAINT user_email_key UNIQUE (email);
ALTER TABLE ONLY public."user" ADD CONSTRAINT user_pkey PRIMARY KEY (id);
