ALTER TABLE ONLY public.audit_log ADD CONSTRAINT audit_log_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.blog_posts ADD CONSTRAINT blog_posts_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.blog_posts ADD CONSTRAINT blog_posts_slug_key UNIQUE (slug);
ALTER TABLE ONLY public.blog_posts ADD CONSTRAINT blog_posts_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('published'::character varying)::text])));
ALTER TABLE ONLY public.business ADD CONSTRAINT business_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.business_owner ADD CONSTRAINT business_owner_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.business_owner_invite ADD CONSTRAINT business_owner_invite_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.charge ADD CONSTRAINT charge_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.concurrent_operations ADD CONSTRAINT concurrent_operations_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT admin_action_requires_staff_user CHECK ((((actor_type = 'admin'::text) AND (staff_user_id IS NOT NULL)) OR ((actor_type = 'system'::text) AND (staff_user_id IS NULL))));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT check_action_source CHECK ((action_source = ANY (ARRAY['admin_ui'::text, 'scheduled_job'::text, 'api'::text])));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT check_actor_type CHECK ((actor_type = ANY (ARRAY['admin'::text, 'system'::text])));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT check_staff_initials_not_un CHECK (((staff_initials <> 'UN'::text) AND (staff_initials <> ''::text)));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT check_staff_name_not_unknown CHECK (((staff_name <> 'Unknown'::text) AND (staff_name <> ''::text)));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT destruction_log_destruction_status_check CHECK ((destruction_status = ANY (ARRAY['scheduled'::text, 'completed'::text])));
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT destruction_log_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.destruction_log ADD CONSTRAINT unique_mail_item_destruction UNIQUE (mail_item_id);
ALTER TABLE ONLY public.download ADD CONSTRAINT download_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.email_change_request ADD CONSTRAINT email_change_request_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.email_preferences ADD CONSTRAINT email_preferences_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.export_job ADD CONSTRAINT export_job_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.export_job ADD CONSTRAINT export_job_status_chk CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'done'::text, 'failed'::text])));
ALTER TABLE ONLY public.file ADD CONSTRAINT file_item_id_key UNIQUE (item_id);
ALTER TABLE ONLY public.file ADD CONSTRAINT file_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.forwarding_charge ADD CONSTRAINT forwarding_charge_forwarding_request_id_key UNIQUE (forwarding_request_id);
ALTER TABLE ONLY public.forwarding_charge ADD CONSTRAINT forwarding_charge_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.forwarding_outbox ADD CONSTRAINT forwarding_outbox_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.forwarding_request ADD CONSTRAINT forwarding_request_pkey PRIMARY KEY (id);
