CREATE OR REPLACE FUNCTION public.cleanup_expired_locks() RETURNS integer LANGUAGE plpgsql AS $function$
DECLARE deleted_count INTEGER;
BEGIN DELETE FROM admin_operation_locks WHERE expires_at < NOW(); GET DIAGNOSTICS deleted_count = ROW_COUNT; RETURN deleted_count; END;
$function$;
CREATE OR REPLACE FUNCTION public.cleanup_old_activity_logs() RETURNS integer LANGUAGE plpgsql AS $function$
DECLARE deleted_count INTEGER;
BEGIN DELETE FROM admin_activity WHERE created_at < NOW() - INTERVAL '90 days'; GET DIAGNOSTICS deleted_count = ROW_COUNT; RETURN deleted_count; END;
$function$;
CREATE OR REPLACE FUNCTION public.cleanup_old_concurrent_operations() RETURNS integer LANGUAGE plpgsql AS $function$
DECLARE deleted_count INTEGER;
BEGIN DELETE FROM concurrent_operations WHERE started_at < NOW() - INTERVAL '7 days' AND status IN ('completed', 'failed'); GET DIAGNOSTICS deleted_count = ROW_COUNT; RETURN deleted_count; END;
$function$;
CREATE OR REPLACE FUNCTION public.safe_timestamp_from_ms(ms_value bigint) RETURNS timestamp with time zone LANGUAGE plpgsql AS $function$ BEGIN IF ms_value > 4102444800000 THEN RETURN NULL; END IF; IF ms_value < 10000000000 THEN RETURN to_timestamp(ms_value); END IF; RETURN to_timestamp(ms_value / 1000); END; $function$;
CREATE OR REPLACE FUNCTION public.trg_forwarding_to_mail_item() RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN UPDATE mail_item SET forwarding_status = NEW.status WHERE id = NEW.mail_item_id; RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.update_system_metrics() RETURNS jsonb LANGUAGE plpgsql AS $function$
DECLARE metrics JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_users', (SELECT COUNT(*) FROM "user" WHERE deleted_at IS NULL),
    'active_users', (SELECT COUNT(*) FROM "user" WHERE deleted_at IS NULL AND last_active_at > EXTRACT(EPOCH FROM NOW() - INTERVAL '30 days') * 1000),
    'total_mail_items', (SELECT COUNT(*) FROM mail_item WHERE deleted = false),
    'pending_forwarding_requests', (SELECT COUNT(*) FROM forwarding_request WHERE status = 'pending'),
    'system_uptime', EXTRACT(EPOCH FROM NOW() - pg_postmaster_start_time()),
    'last_updated', NOW()) INTO metrics;
  RETURN metrics;
END;
$function$;
CREATE TRIGGER forwarding_request_status_mirror AFTER UPDATE OF status ON public.forwarding_request FOR EACH ROW EXECUTE FUNCTION trg_forwarding_to_mail_item();
